const DECISION_NOTES=[{"category": "🛏️ Bed frame", "html": "<span class=\"nm\">Timeless Bed Frame (Queen, grey)</span><span class=\"wy\">Grey, 2 storage drawers. ✅ In stock (Queen confirmed 3 Oct). Light oak look with a low headboard. ⚠️ Only Queen/Double, and the mattress is Queen XL, so see Shopping for Queen XL lookalikes. Decided 2 Oct.</span>", "shop": "MFA Online", "price": "R3,199"}, {"category": "🌙 Mattress", "html": "<span class=\"nm\">✅ ORDERED 29 Oct: COSOVA 26cm Cloud 3.0 Hybrid Pocket Spring (Queen XL)</span><span class=\"wy\">Takealot order 228845519, paid 29 Oct. ✅ <b>Delivered Mon 2 Nov.</b> Medium (6/10), pocket springs. Queen XL = 152×200cm, 12cm longer than a normal Queen. The same order also has a COSOVA 20cm Queen (R3,199) for Sean's sister-in-law.</span>", "shop": "Takealot", "price": "R3,999"}, {"category": "📺 TV", "html": "<span class=\"nm\">✅ BOUGHT: Skyworth 55\" QLED 120Hz Google TV</span><span class=\"wy\">120Hz + Google TV + Dolby Audio. Bought on Takealot (R6,299) after the Amazon order was cancelled; the Amazon R6,299 refund was processed 30 Oct. ✅ <b>Delivered Mon 2 Nov.</b> Strap it (and the stand) to the wall.</span>", "shop": "Takealot", "price": "R6,299"}, {"category": "❄️ Fridge", "html": "<span class=\"nm\">Defy 323L DAC627 Combi (Satin Metallic)</span><span class=\"wy\">Bottom-freezer combi, 323L, water dispenser, A+. Same Defy repair-network logic as the washer. ✅ Confirmed in stock at Takealot's Joburg warehouse. Swapped in 3 Oct — the Hisense went out of stock. ⚠️ Might not need it: ask if Baker Rd comes with a fridge (Acacia did, but declined us 21 Oct), and Mom might pass hers on (18 Oct, not confirmed).</span>", "shop": "Takealot", "price": "R6,499"}, {"category": "🧺 Washer", "html": "<span class=\"nm\">Defy 8kg DAW408B Front Loader (Midnight Black)</span><span class=\"wy\">Front-loader, A+++, SteamCure. Defy = best local repair network in SA. Decided 2 Oct. ⚠️ Mom might pass on her washer (18 Oct, not confirmed), so hold off until that's settled.</span>", "shop": "MHC World", "price": "R5,699"}, {"category": "☕ Coffee table", "html": "<span class=\"nm\">LAZAVA Rustic Lift-Top Coffee Table</span><span class=\"wy\">⭐ Mishka's pick (20 Oct), replaces the LASA two-tier. Rustic brown, 100 × 60cm, the top lifts to ~62cm, hidden storage. ✅ In stock, R1,608.87 (checked 20 Oct). JHB delivery from 21 Oct, 30-day returns.</span>", "shop": "LASA Africa", "price": "R1,609"}, {"category": "🗄️ TV stand", "html": "<span class=\"nm\">✅ ARRIVED (ordered 29 Oct): TV-17 Berlin 160cm Rustic TV Stand (2 fabric drawers + shelves)</span><span class=\"wy\">Bought direct from Artisan Furniture (artisansa.co.za), confirmation #8NV9G8855, R1,103.19 incl. delivery with the SAVE5 code. Nico (Artisan, WhatsApp) asked for a Friday 30 Oct afternoon delivery to Victoria Square, but warned it could slip to Mon/Tue; free collection from their Germiston warehouse is the backup. Strap it to the wall.</span>", "shop": "Artisan Furniture", "price": "R1,103"}, {"category": "🛋️ Couch", "html": "<span class=\"nm\">✅ DELIVERED: Osaka U-shape couch (ordered 20 Oct)</span><span class=\"wy\">Made to order by Polokwane Lifestyle Furnitures (Pty) Ltd, reg 2025/441749/07. Fabric: the top-right swatch Sean + Mishka picked (light taupe/beige linen-look). R10,999 + R600 delivery = <b>R11,599</b>. ✅ <b>Deposit R5,799.50 paid 20 Oct</b> (EFT, FNB). ✅ Balance R5,799.50 paid on delivery, so fully paid. Delivery promised <b>2 Nov</b>. ⚠️ Their invoice says 23 Emerald Blvd, so make sure they have Unit 30, 114 Victoria Square. Invoice 1008.</span>", "shop": "Polokwane Lifestyle Furnitures", "price": "R11,599"}, {"category": "💻 Laptop", "html": "<span class=\"nm\">✅ PAID 2 Nov: Dell G5 5587 (i7, 16GB, 512GB)</span><span class=\"wy\">Mishka paid Device Shop by EFT on 2 Nov (FNB, ref MAC015). Arriving in a day or so. The day it lands: check the NVIDIA card in Task Manager, hinges, ports and charger, and report anything wrong with photos within 48 hours.</span>", "shop": "Device Shop", "price": "R8,913"}];
